-- 创建自定义类型
CREATE TYPE address AS (
    street text,
    city text,
    zipcode varchar(10)
);

-- 在表中使用
CREATE TABLE customers (
    id serial PRIMARY KEY,
    name text,
    home_address address,  -- 直接使用自定义类型
    shipping_addresses address[]  -- 地址数组
);

-- 父表
CREATE TABLE vehicles (
    id serial PRIMARY KEY,
    name text,
    max_speed integer
);

-- 子表继承
CREATE TABLE cars (
    fuel_type text
) INHERITS (vehicles);

CREATE TABLE trucks (
    load_capacity integer
) INHERITS (vehicles);

-- 查询会包含所有子表数据
SELECT * FROM vehicles;

-- 主表，存储公共属性和类型
CREATE TABLE entities (
    id SERIAL PRIMARY KEY,
    type VARCHAR(20) NOT NULL, -- 'USER', 'ADMIN', 'GUEST'
    created_at TIMESTAMP DEFAULT NOW()
);
-- 详情表，存储特有属性，通过外键关联
CREATE TABLE user_details (
    entity_id INT PRIMARY KEY REFERENCES entities(id),
    email VARCHAR(100) UNIQUE,
    phone VARCHAR(20)
);
CREATE TABLE admin_details (
    entity_id INT PRIMARY KEY REFERENCES entities(id),
    department VARCHAR(50),
    permission_level INT
);

CREATE TABLE products (
    id SERIAL PRIMARY KEY,
    name TEXT,
    type VARCHAR(20) NOT NULL,
    attributes JSONB, -- 存储不同类型的特有属性
    CONSTRAINT valid_attributes CHECK (
        (type = 'book' AND attributes ? 'isbn') OR
        (type = 'clothing' AND attributes ? 'size')
    )
);

-- 自定义复数类型
CREATE TYPE complex AS (r float8, i float8);

-- 自定义加法操作符
CREATE FUNCTION complex_add(complex, complex)
RETURNS complex AS $$
    SELECT ($1.r + $2.r, $1.i + $2.i)::complex;
$$ LANGUAGE SQL;

CREATE OPERATOR + (
    leftarg = complex,
    rightarg = complex,
    procedure = complex_add
);

-- 使用自定义操作符
SELECT (1.0,1.0)::complex + (2.0,3.0)::complex;

-- 存储整个JSON文档(JSONB类型)
CREATE TABLE products (
    id serial PRIMARY KEY,
    attributes jsonb  -- 支持索引和深度查询
);

-- 查询JSON内部字段
SELECT attributes->>'color' FROM products 
WHERE attributes @> '{"category":"electronics"}';

JSONB 列可以存储 JSON 标准支持的所有数据类型：字符串、数字、布尔值、null、对象（字典）和数组。这些类型可以任意嵌套。

CREATE TABLE user_profiles (
    id SERIAL PRIMARY KEY,
    name TEXT,
    preferences JSONB -- 用户偏好设置
);

INSERT INTO user_profiles (name, preferences) VALUES
('Alice', '{"theme": "dark", "notifications": {"email": true, "sms": false}, "tags": ["admin", "editor"]}'::jsonb),
('Bob', '{"theme": "light", "settings": {"language": "zh-CN", "timezone": "Asia/Shanghai"}}'::jsonb);

-- 为 preferences 列创建默认的 GIN 索引（支持 @>, ?, ?|, ?& 操作符）
CREATE INDEX idx_user_profiles_preferences ON user_profiles USING GIN (preferences);

-- 创建更精细的 JSON 路径表达式索引
CREATE INDEX idx_user_profiles_theme ON user_preferences USING GIN ((preferences->'theme'));

-- 创建一个 JSONB 对象
SELECT jsonb_build_object('name', 'Alice', 'age', 30);

-- 将多行结果聚合为一个 JSONB 数组
SELECT jsonb_agg(name) FROM user_profiles;

-- 修改 JSONB 数据（PostgreSQL 14+ 支持 jsonb_set）
UPDATE user_profiles 
SET preferences = jsonb_set(preferences, '{theme}', '"light"')
WHERE name = 'Alice';

-- 为 preferences 列创建默认的 GIN 索引（支持 @>, ?, ?|, ?& 操作符）
CREATE INDEX idx_user_profiles_preferences ON user_profiles USING GIN (preferences);

-- 创建更精细的 JSON 路径表达式索引
CREATE INDEX idx_user_profiles_theme ON user_preferences USING GIN ((preferences->'theme'));
